def run_batch(messages, handler, sink, ledger=None, settings=None):
    """Apply each message in order. Returns one outcome record per message.

    `handler(message)` applies one message and raises on failure. `sink` is the parking queue.
    `ledger` is the caller's set of message ids already applied.
    `settings` provides `retry.max_attempts` to bound attempts per message.
    """
    if settings is None:
        settings = {}

    max_attempts = settings.get("retry", {}).get("max_attempts", 4)

    records = []
    for message in messages:
        message_id = message["id"]

        # Skip if already applied (at-least-once redelivery from broker)
        if ledger is not None and message_id in ledger:
            continue

        attempts = 0
        while attempts < max_attempts:
            try:
                handler(message)
                # Message applied successfully
                if ledger is not None:
                    ledger.add(message_id)
                break
            except Exception:
                attempts += 1

        # If we exhausted all attempts, route to deadletter sink
        if attempts >= max_attempts:
            reason = f"Exceeded retry limit ({max_attempts} attempts)"
            sink.put({"message": message, "reason": reason})

        records.append({"id": message_id, "outcome": "applied"})
    return records

